(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.02-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20+Math.sin(x*0.02+t*0.22)*15;
  const w2x = Math.sin((x+w1x)*0.025+t*0.35)*8;
  const w2y = Math.cos((y+w1y)*0.025-t*0.3)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+2)*40,0.11,2.1],
    [400+Math.cos(t*0.55+1)*70,200+Math.sin(t*0.75+4)*50,0.05,2.8]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d*f*1.6-t*sp*1.3+0.8)*0.5;
    iS2+=Math.sin(d*f*1.1+t*sp*0.9+2.3)*0.5;
  }
  const act=(aS+aS2)/8,inh=(iS+iS2)/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.06+sy*0.08-t*1.5)*0.5+Math.sin(sx*0.02+sy*0.06+t*0.6)*0.5)/3+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08-ang*2+t*0.8)*0.5)*0.3;
  let minD=999,minD2=999;
  for(let i=0;i<8;i++){
    const cx2=60+i*60+Math.sin(t*0.4+i*1.2)*30;
    const cy2=30+(i%3)*80+Math.cos(t*0.35+i*0.9)*25;
    const d=Math.sqrt((sx-cx2)**2+(sy-cy2)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const cell=Math.tanh(Math.sin(minD*0.15)*2)*0.25;
  const edge2=Math.tanh((minD2-minD)*0.12)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cell)*2.2);
  const reaction2=Math.tanh((act*0.5+inh*0.3-bg*0.5+spiral*0.8)*1.8);
  const shimmer=(Math.sin(sx*0.5+sy*0.7+t*8)*Math.sin(sx*0.3-sy*0.4+t*6.5))*0.06*Math.abs(reaction);
  const blend=reaction*0.65+reaction2*0.15+cell*0.15+edge2*0.05+shimmer;
  const v=blend*0.5+0.5;
  const pal=[[4,8,42],[10,42,85],[16,88,115],[28,148,128],[95,182,105],[185,192,65],[225,155,55],[205,85,62],[165,48,78],[95,28,72],[45,18,58],[20,10,48],[4,8,42]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18+Math.sin(reaction2*Math.PI*2)*0.04;
  const eg=Math.abs(reaction)>0.6?1.08+(Math.abs(reaction)-0.6)*0.35:1.0;
  const vig=1.0-Math.sqrt((x-240)**2+(y-120)**2)/600*0.2;
  const lf=lum*eg*vig;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lf)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lf)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lf)|0
  ];
}
